#include "projectile/pipeline.hpp"
#include <opencv2/highgui.hpp>
#include <chrono>
#include <algorithm>
#include <iostream>
namespace projectile { Pipeline::Pipeline(Config c):config_(std::move(c)),capture_(config_.camera_index,config_.width,config_.height,config_.fps,config_.video_path,buffer_),preprocessor_(config_),motion_(config_),detector_(config_),tracker_(config_),trails_(config_.trail_length),analyzer_(config_),visualizer_(config_){} int Pipeline::run(){capture_.start();if(!capture_.is_open())return 1;std::uint64_t n=0;auto start=std::chrono::steady_clock::now();FramePacket p;while(!stopping_&&buffer_.wait_pop(p,stopping_)){if(++n%std::max(1,config_.frame_skip)!=0)continue;auto full=p.frame;auto [roi,offset]=preprocessor_.roi(full);auto scaled=preprocessor_.scale(roi);auto gray=preprocessor_.gray(scaled);auto masks=motion_.process(scaled,gray);auto detections=detector_.detect(masks.cleaned);auto tracks=tracker_.update(detections);double inv=config_.process_scale<1?1/config_.process_scale:1;for(auto&t:tracks){t.center.x=float(t.center.x*inv+offset.x);t.center.y=float(t.center.y*inv+offset.y);t.box.x=int(t.box.x*inv+offset.x);t.box.y=int(t.box.y*inv+offset.y);t.box.width=int(t.box.width*inv);t.box.height=int(t.box.height*inv);}trails_.update(tracks);trails_.prune(tracks);auto arcs=analyzer_.analyze(trails_,tracks,full.size());if(config_.display&&!config_.headless){auto out=visualizer_.draw(full,tracks,trails_,arcs,n,masks.warmed_up);cv::imshow("Projectile Detector",out);int key=cv::waitKey(1);if(key==27||key=='q'||key=='Q')break;}}capture_.stop();if(config_.display&&!config_.headless)cv::destroyAllWindows();if(config_.verbose_metrics){auto sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::cout<<"capture_frames="<<capture_.captured()<<" processed_frames="<<n<<" dropped_frames="<<buffer_.dropped()<<" processing_fps="<<(sec>0?n/sec:0)<<"\n";}return 0;} }
